import{_ as e,o,c as i,a5 as n}from"./chunks/framework.DJo0M80U.js";const u=JSON.parse('{"title":"JS获取浏览器窗口大小 获取屏幕，浏览器，网页高度宽度（转）","description":"2019 03 05阅读 1K0 网页可见区域宽：document.body.clientWidth 网页可见区域高：document.body.clientHeight 网页可见区域宽：document.body.offsetWidth (包括边线的宽) 网页可见区域高：doc。","frontmatter":{"title":"JS获取浏览器窗口大小 获取屏幕，浏览器，网页高度宽度（转）","date":"2026-08-11T00:00:00.000Z","categories":["JavaScript 系统教程"],"tags":["JavaScript","前端","教程","OneNote","浏览器与 Web API"],"description":"2019 03 05阅读 1K0 网页可见区域宽：document.body.clientWidth 网页可见区域高：document.body.clientHeight 网页可见区域宽：document.body.offsetWidth (包括边线的宽) 网页可见区域高：doc。","sidebarWeight":35,"lastUpdated":false,"feed":false,"source":"onenote","sourceNote":"OneNote/b-原生js/DOM/JS获取浏览器窗口大小 获取屏幕，浏览器，网页高度宽度（转）.md"},"headers":[],"relativePath":"posts/JavaScript系统教程/04-浏览器与 Web API/JS获取浏览器窗口大小 获取屏幕，浏览器，网页高度宽度（转）.md","filePath":"posts/JavaScript系统教程/04-浏览器与 Web API/JS获取浏览器窗口大小 获取屏幕，浏览器，网页高度宽度（转）.md"}'),d={name:"posts/JavaScript系统教程/04-浏览器与 Web API/JS获取浏览器窗口大小 获取屏幕，浏览器，网页高度宽度（转）.md"};function c(l,t,h,r,a,s){return o(),i("div",null,[...t[0]||(t[0]=[n('<div><h1 id="js获取浏览器窗口大小-获取屏幕-浏览器-网页高度宽度-转" tabindex="-1">JS获取浏览器窗口大小 获取屏幕，浏览器，网页高度宽度（转） <a class="header-anchor" href="#js获取浏览器窗口大小-获取屏幕-浏览器-网页高度宽度-转" aria-label="Permalink to &quot;JS获取浏览器窗口大小 获取屏幕，浏览器，网页高度宽度（转）&quot;">​</a></h1><blockquote><p>本节目标：理解“JS获取浏览器窗口大小 获取屏幕，浏览器，网页高度宽度（转）”的核心思路，并能把它用于实际开发或面试表达。 2019-03-05阅读 1K0</p></blockquote><p>网页可见区域宽：document.body.clientWidth 网页可见区域高：document.body.clientHeight 网页可见区域宽：document.body.offsetWidth (包括边线的宽) 网页可见区域高：document.body.offsetHeight (包括边线的宽) 网页正文全文宽：document.body.scrollWidth 网页正文全文高：document.body.scrollHeight 网页被卷去的高：document.body.scrollTop 网页被卷去的左：document.body.scrollLeft 网页正文部分上：window.screenTop 网页正文部分左：window.screenLeft 屏幕分辨率的高：window.screen.height 屏幕分辨率的宽：window.screen.width 屏幕可用工作区高度：window.screen.availHeight 屏幕可用工作区宽度：window.screen.availWidth HTML精确定位:scrollLeft,scrollWidth,clientWidth,offsetWidth scrollHeight: 获取对象的滚动高度。 scrollLeft:设置或获取位于对象左边界和窗口中目前可见内容的最左端之间的距离 scrollTop:设置或获取位于对象最顶端和窗口中可见内容的最顶端之间的距离 scrollWidth:获取对象的滚动宽度 offsetHeight:获取对象相对于版面或由父坐标 offsetParent 属性指定的父坐标的高度 offsetLeft:获取对象相对于版面或由 offsetParent 属性指定的父坐标的计算左侧位置 offsetTop:获取对象相对于版面或由 offsetTop 属性指定的父坐标的计算顶端位置 event.clientX 相对文档的水平座标 event.clientY 相对文档的垂直座标 event.offsetX 相对容器的水平坐标 event.offsetY 相对容器的垂直坐标 document.documentElement.scrollTop 垂直方向滚动的值 event.clientX+document.documentElement.scrollTop 相对文档的水平座标+垂直方向滚动的量 IE，FireFox 差异如下： IE6.0、FF1.06+： clientWidth = width + padding clientHeight = height + padding offsetWidth = width + padding + border offsetHeight = height + padding + border IE5.0/5.5： clientWidth = width - border clientHeight = height - border offsetWidth = width offsetHeight = height (需要提一下：CSS中的margin属性，与clientWidth、offsetWidth、clientHeight、offsetHeight均无关)</p><p>网页可见区域宽： document.body.clientWidth 网页可见区域高： document.body.clientHeight 网页可见区域宽： document.body.offsetWidth (包括边线的宽) 网页可见区域高： document.body.offsetHeight (包括边线的高) 网页正文全文宽： document.body.scrollWidth 网页正文全文高： document.body.scrollHeight 网页被卷去的高： document.body.scrollTop 网页被卷去的左： document.body.scrollLeft 网页正文部分上： window.screenTop 网页正文部分左： window.screenLeft 屏幕分辨率的高： window.screen.height 屏幕分辨率的宽： window.screen.width 屏幕可用工作区高度： window.screen.availHeight 屏幕可用工作区宽度： window.screen.availWidth</p><p>－－－－－－－－－－－－－－－－－－－</p><p>技术要点 本节代码主要使用了Document对象关于窗口的一些属性，这些属性的主要功能和用法如下。 要得到窗口的尺寸，对于不同的浏览器，需要使用不同的属性和方法：若要检测窗口的真实尺寸，在Netscape下需要使用Window的属性；在IE下需要 深入Document内部对body进行检测；在DOM环境下，若要得到窗口的尺寸，需要注意根元素的尺寸，而不是元素。 Window对象的innerWidth属性包含当前窗口的内部宽度。Window对象的innerHeight属性包含当前窗口的内部高度。 Document对象的body属性对应HTML文档的标签。Document对象的documentElement属性则表示HTML文档的根节点。 document.body.clientHeight表示HTML文档所在窗口的当前高度。document.body. clientWidth表示HTML文档所在窗口的当前宽度。 实现代码</p><p>&lt;!DOCTYPE html PUBLIC &quot;-//W3C//DTD XHTML 1.0 Transitional//EN&quot; &quot;<a href="http://www.w3.org/TR/xhtml1/DTD/xhtml1-transitional.dtd" target="_blank" rel="noreferrer">http://www.w3.org/TR/xhtml1/DTD/xhtml1-transitional.dtd</a>&quot;&gt; &lt;html xmlns=&quot;<a href="http://www.w3.org/1999/xhtml" target="_blank" rel="noreferrer">http://www.w3.org/1999/xhtml</a>&quot;&gt; &lt;head&gt; &lt;title&gt;请调整浏览器窗口&lt;/title&gt; &lt;meta http-equiv=&quot;content-type&quot; content=&quot;text/html; charset=gb2312&quot;&gt; &lt;/head&gt; &lt;body&gt; &lt;h2 align=&quot;center&quot;&gt;请调整浏览器窗口大小&lt;/h2&gt;&lt;hr&gt; &lt;form action=&quot;#&quot; method=&quot;get&quot; name=&quot;form1&quot; id=&quot;form1&quot;&gt; &lt;!--显示浏览器窗口的实际尺寸--&gt; 浏览器窗口 的 实际高度: &lt;input type=&quot;text&quot; name=&quot;availHeight&quot; size=&quot;4&quot;&gt;&lt;br&gt; 浏览器窗口 的 实际宽度: &lt;input type=&quot;text&quot; name=&quot;availWidth&quot; size=&quot;4&quot;&gt;&lt;br&gt; &lt;/form&gt; &lt;script type=&quot;text/javascript&quot;&gt; &lt;!-- var winWidth = 0; var winHeight = 0; function findDimensions() //函数：获取尺寸 { //获取窗口宽度 if (window.innerWidth) winWidth = window.innerWidth; else if ((document.body) &amp;&amp; (document.body.clientWidth)) winWidth = document.body.clientWidth; //获取窗口高度 if (window.innerHeight) winHeight = window.innerHeight; else if ((document.body) &amp;&amp; (document.body.clientHeight)) winHeight = document.body.clientHeight; //通过深入Document内部对body进行检测，获取窗口大小 if (document.documentElement &amp;&amp; document.documentElement.clientHeight &amp;&amp; document.documentElement.clientWidth) { winHeight = document.documentElement.clientHeight; winWidth = document.documentElement.clientWidth; } //结果输出至两个文本框 document.form1.availHeight.value= winHeight; document.form1.availWidth.value= winWidth; } findDimensions(); //调用函数，获取数值 window.onresize=findDimensions; //--&gt; &lt;/script&gt; &lt;/body&gt; &lt;/html&gt;</p><p>源程序解读</p><p>（1）程序首先建立一个表单，包含两个文本框，用于显示窗口当前的宽度和高度，并且，其数值会随窗口大小的改变而变化。</p><p>（2）在随后的JavaScript代码中，首先定义了两个变量winWidth和winHeight，用于保存窗口的高度值和宽度值。</p><p>（3）然后，在函数findDimensions ( )中，使用window.innerHeight和window.innerWidth得到窗口的高度和宽度，并将二者保存在前述两个变量中。</p><p>（4）再通过深入Document内部对body进行检测，获取窗口大小，并存储在前述两个变量中。</p><p>（5）在函数的最后，通过按名称访问表单元素，结果输出至两个文本框。</p><p>（6）在JavaScript代码的最后，通过调用findDimensions ( )函数，完成整个操作。</p></div>',1)])])}const p=e(d,[["render",c]]);export{u as __pageData,p as default};
